1	// Draft7Validator core: keyword dispatch, $ref resolution, descend/evolve
2	// helpers, is_valid and check_schema.
3	//
4	// Keyword implementations live in ./keywords/*.mjs. Each keyword function
5	// has the signature:
6	//     (validator, keywordValue, instance, schema) -> iterable<ValidationError>
7	// Freshly created errors carry an empty `path`; `validator.descend` is used
8	// to validate subschemas and prepends the path element. The dispatch loop
9	// below overwrites error.validator with the keyword name at each level as
10	// errors bubble up, matching jsonschema's behaviour (this is what makes
11	// ErrorTree collapse same-keyword errors at the same path).
12	
13	import { ValidationError, SchemaError } from './errors.mjs';
14	import { isType } from './types.mjs';
15	import { META_SCHEMA } from './metaSchema.mjs';
16	import * as core from './keywords/core.mjs';
17	import * as numeric from './keywords/numeric.mjs';
18	import * as string from './keywords/string.mjs';
19	import * as array from './keywords/array.mjs';
20	import * as object from './keywords/object.mjs';
21	import * as logical from './keywords/logical.mjs';
22	
23	const VALIDATORS = {
24	  // core
25	  type: core.type,
26	  enum: core.enum_,
27	  const: core.const_,
28	  // numeric
29	  multipleOf: numeric.multipleOf,
30	  maximum: numeric.maximum,
31	  exclusiveMaximum: numeric.exclusiveMaximum,
32	  minimum: numeric.minimum,
33	  exclusiveMinimum: numeric.exclusiveMinimum,
34	  // string
35	  maxLength: string.maxLength,
36	  minLength: string.minLength,
37	  pattern: string.pattern,
38	  // array
39	  items: array.items,
40	  additionalItems: array.additionalItems,
41	  contains: array.contains,
42	  maxItems: array.maxItems,
43	  minItems: array.minItems,
44	  uniqueItems: array.uniqueItems,
45	  // object
46	  properties: object.properties,
47	  patternProperties: object.patternProperties,
48	  additionalProperties: object.additionalProperties,
49	  required: object.required,
50	  dependencies: object.dependencies,
51	  propertyNames: object.propertyNames,
52	  maxProperties: object.maxProperties,
53	  minProperties: object.minProperties,
54	  // logical
55	  allOf: logical.allOf,
56	  anyOf: logical.anyOf,
57	  oneOf: logical.oneOf,
58	  not: logical.not,
59	  if: logical.if_,
60	};
61	
62	export class Draft7Validator {
63	  static META_SCHEMA = META_SCHEMA;
64	  static VALIDATORS = VALIDATORS;
65	
66	  constructor(schema) {
67	    this.schema = schema;
68	  }
69	
70	  isType(instance, type) {
71	    return isType(instance, type);
72	  }
73	
74	  // Resolve a $ref string against the root schema document.
75	  // Supports "#" and local JSON pointers ("#/definitions/foo").
76	  resolveRef(ref) {
77	    if (typeof ref !== 'string' || !ref.startsWith('#')) {
78	      throw new Error(`Unresolvable reference: ${ref}`);
79	    }
80	    const fragment = decodeURIComponent(ref.slice(1));
81	    if (fragment === '') {
82	      return this.schema;
83	    }
84	    if (!fragment.startsWith('/')) {
85	      throw new Error(`Unresolvable reference: ${ref}`);
86	    }
87	    let target = this.schema;
88	    for (const rawPart of fragment.slice(1).split('/')) {
89	      const part = rawPart.replace(/~1/g, '/').replace(/~0/g, '~');
90	      if (Array.isArray(target)) {
91	        target = target[Number(part)];
92	      } else if (target !== null && typeof target === 'object') {
93	        target = target[part];
94	      } else {
95	        throw new Error(`Unresolvable reference: ${ref}`);
96	      }
97	      if (target === undefined) {
98	        throw new Error(`Unresolvable reference: ${ref}`);
99	      }
100	    }
101	    return target;
102	  }
103	
104	  *iter_errors(instance) {
105	    yield* this._iterErrors(instance, this.schema, []);
106	  }
107	
108	  *_iterErrors(instance, schema, basePath) {
109	    if (schema === true) return;
110	    if (schema === false) {
111	      const error = new ValidationError(
112	        `False schema does not allow ${JSON.stringify(instance)}`
113	      );
114	      error.path = basePath;
115	      error.instance = instance;
116	      error.schema = schema;
117	      error.validator = false;
118	      error.validatorValue = false;
119	      yield error;
120	      return;
121	    }
122	    if (schema === null || typeof schema !== 'object') return;
123	
124	    // Draft-07 semantics: a $ref replaces its sibling keywords.
125	    if (typeof schema.$ref === 'string') {
126	      const resolved = this.resolveRef(schema.$ref);
127	      yield* this._iterErrors(instance, resolved, basePath);
128	      return;
129	    }
130	
131	    for (const [k, v] of Object.entries(schema)) {
132	      const fn = VALIDATORS[k];
133	      if (fn === undefined) continue;
134	      const errors = fn(this, v, instance, schema);
135	      if (!errors) continue;
136	      for (const error of errors) {
137	        error.validator = k;
138	        error.validatorValue = v;
139	        error.instance = instance;
140	        error.schema = schema;
141	        error.path = [...basePath, ...error.path];
142	        error.schemaPath = [k, ...error.schemaPath];
143	        yield error;
144	      }
145	    }
146	  }
147	
148	  // Validate `instance` against `subschema`, yielding errors whose paths are
149	  // prefixed with `pathElement` (pass null/undefined to keep the path).
150	  *descend(instance, subschema, pathElement) {
151	    const prefix = pathElement === null || pathElement === undefined ? [] : [pathElement];
152	    for (const error of this._iterErrors(instance, subschema, prefix)) {
153	      yield error;
154	    }
155	  }
156	
157	  // True if `instance` is valid against `subschema`.
158	  isValidAgainst(instance, subschema) {
159	    return this._iterErrors(instance, subschema, []).next().done;
160	  }
161	
162	  is_valid(instance) {
163	    return this._iterErrors(instance, this.schema, []).next().done;
164	  }
165	
166	  // Validates a schema against the Draft-07 meta-schema. Returns nothing
167	  // (Python returns None); throws SchemaError if the schema is invalid.
168	  static check_schema(schema) {
169	    const validator = new Draft7Validator(META_SCHEMA);
170	    const errors = [...validator._iterErrors(schema, META_SCHEMA, [])];
171	    if (errors.length > 0) {
172	      const best = errors[0];
173	      throw new SchemaError(
174	        `The schema is invalid: ${best.message}`,
175	        errors
176	      );
177	    }
178	  }
179	
180	  check_schema(schema) {
181	    return Draft7Validator.check_schema(schema);
182	  }
183	}

