import { execFileSync } from 'node:child_process';
let pass = 0, fail = 0;
for (const [a, b] of cases) {
  let ref, mine;
  try {
    ref = execFileSync('/workspace/dataset/test18_executable', ['--a', a, '--b', b], {stdio:['ignore','pipe','ignore']}).toString();
  } catch (e) { ref = 'REF_ERROR:' + e.status; }
  try {
    mine = execFileSync('node', ['/output/test18.mjs', '--a', a, '--b', b], {stdio:['ignore','pipe','ignore']}).toString();
  } catch (e) { mine = 'MINE_ERROR:' + e.status; }
  if (ref === mine) { pass++; }
  else {
    fail++;
    console.log('MISMATCH', a, b);
    console.log('--- ref ---\n' + ref + '--- mine ---\n' + mine);
  }
}
