// Core keywords: type, enum, const.
//
// Each function matches jsonschema's _keywords.py behaviour: `type` yields a
// single error if the instance matches none of the given simple types, `enum`
// and `const` yield a single error on mismatch.
//
// Equality for enum/const follows jsonschema._utils.equal: booleans are
// strictly distinct from numbers (True != 1, unlike Python's ==), numbers
// compare by value (1 == 1.0), and arrays/objects compare recursively with
// the same rule. NOTE: `deepEqual` from ../types.mjs uses the older
// bool-as-number `unbool` semantics and does NOT match the reference
// executable, so the correct equality is implemented locally here.

import { ValidationError } from '../errors.mjs';

function equal(one, two) {
  const oneBool = typeof one === 'boolean';
  const twoBool = typeof two === 'boolean';
  if (oneBool || twoBool) {
    return oneBool && twoBool && one === two;
  }
  if (Array.isArray(one) && Array.isArray(two)) {
    if (one.length !== two.length) return false;
    for (let i = 0; i < one.length; i++) {
      if (!equal(one[i], two[i])) return false;
    }
    return true;
  }
  if (isObject(one) && isObject(two)) {
    const keys = Object.keys(one);
    if (keys.length !== Object.keys(two).length) return false;
    for (const key of keys) {
      if (!Object.prototype.hasOwnProperty.call(two, key)) return false;
      if (!equal(one[key], two[key])) return false;
    }
    return true;
  }
  return one === two;
}

function isObject(v) {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

export function* type(validator, value, instance, schema) {
  const types = Array.isArray(value) ? value : [value];
  if (!types.some((t) => validator.isType(instance, t))) {
    yield new ValidationError(
      `${JSON.stringify(instance)} is not of type ${JSON.stringify(value)}`
    );
  }
}

export function* enum_(validator, value, instance, schema) {
  if (!value.some((element) => equal(element, instance))) {
    yield new ValidationError(
      `${JSON.stringify(instance)} is not one of ${JSON.stringify(value)}`
    );
  }
}

export function* const_(validator, value, instance, schema) {
  if (!equal(value, instance)) {
    yield new ValidationError(`${JSON.stringify(value)} was expected`);
  }
}

